<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span>value <span class="token keyword">for</span> row <span class="token keyword">in</span> grid_2d <span class="token keyword">for</span> value <span class="token keyword">in</span> row<span class="token punctuation">]</span></span>
